/*{
  "DESCRIPTION": "Gently falling snow with twinkling lights",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "snowColor", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "bgColor", "TYPE": "color", "DEFAULT": [0.0, 0.0, 0.2, 1.0] },
    { "NAME": "fallSpeed", "TYPE": "float", "MIN": 0.1, "MAX": 2.0, "DEFAULT": 0.5 },
    { "NAME": "density", "TYPE": "float", "MIN": 0.1, "MAX": 2.0, "DEFAULT": 1.0 }
  ]
}*/

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

float snowflake(vec2 uv, float time) {
  vec2 p = uv * 12.0;
  vec2 i = floor(p);
  vec2 f = fract(p);

  float h = hash(i + vec2(137.0, 241.0));
  float yOffset = fract(time * fallSpeed * 0.3 + h);

  float dy = fract(f.y + yOffset);
  float dx = fract(f.x + sin(h * 6.28) * 0.1);

  float d = length(vec2(dx - 0.5, dy - 0.5));
  float flake = smoothstep(0.35, 0.0, d);

  float twinkle = 0.5 + 0.5 * sin(TIME * 3.0 + h * 6.28);
  return flake * (0.6 + 0.4 * twinkle);
}

void main() {
  vec2 uv = isf_FragNormCoord;

  vec3 bg = bgColor.rgb;

  float snow = 0.0;
  for (int i = 0; i < 4; i++) {
    vec2 offset = vec2(float(i) * 0.25, 0.0);
    snow += snowflake(uv + offset, TIME) * density;
  }

  snow = min(1.0, snow);

  vec3 color = mix(bg, snowColor.rgb, snow * 0.9);

  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "Fire rising from the bottom with flickering flames and warm colors",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorBase", "TYPE": "color", "DEFAULT": [1.0, 0.2, 0.0, 1.0] },
    { "NAME": "colorTip", "TYPE": "color", "DEFAULT": [1.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.5 },
    { "NAME": "height", "TYPE": "float", "MIN": 0.1, "MAX": 2.0, "DEFAULT": 1.0 },
    { "NAME": "turbulence", "TYPE": "float", "MIN": 0.0, "MAX": 2.0, "DEFAULT": 1.0 }
  ]
}*/

float hash(float n) {
  return fract(sin(n) * 43758.5453);
}

float noise(float x) {
  float i = floor(x);
  float f = fract(x);
  f = f * f * (3.0 - 2.0 * f);
  return mix(hash(i), hash(i + 1.0), f);
}

void main() {
  vec2 uv = isf_FragNormCoord;

  float fireHeight = uv.y * height;
  float time = TIME * speed * 0.5;

  float flicker = noise(fireHeight * 3.0 + time);
  float wave = sin(fireHeight * 6.28 + time) * 0.3;
  float turbulenceNoise = noise(uv.x * 8.0 + time * turbulence) * 0.4;

  float distortion = wave + turbulenceNoise + flicker * 0.3;
  float shimmer = noise(uv.x * 4.0 - fireHeight * 2.0 + time * 1.5) * 0.5 + 0.5;

  float fireMask = 1.0 - fireHeight;
  fireMask = smoothstep(0.0, 0.7, fireMask - abs(distortion) * 0.5);
  fireMask *= shimmer;

  vec3 fireColor = mix(colorBase.rgb, colorTip.rgb, fireHeight);
  fireColor *= (1.0 + flicker * 0.4);

  gl_FragColor = vec4(fireColor * fireMask, 1.0);
}

/*{
  "DESCRIPTION": "Candy cane stripes scrolling diagonally across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "stripeWidth", "TYPE": "float", "MIN": 0.02, "MAX": 0.3, "DEFAULT": 0.1 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  float diagonal = uv.x + uv.y - TIME * speed * 0.5;
  float stripe = fract(diagonal / stripeWidth);
  float band = step(0.5, stripe);

  vec3 finalColor = mix(colorA.rgb, colorB.rgb, band);
  gl_FragColor = vec4(finalColor, 1.0);
}

/*{
  "DESCRIPTION": "Smooth fade between colors across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 }
  ]
}*/

void main() {
  float fade = sin(TIME * speed * 0.5) * 0.5 + 0.5;
  vec3 color = mix(colorA.rgb, colorB.rgb, fade);
  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "Twinkling stars scattered across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "starColor", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "backgroundColor", "TYPE": "color", "DEFAULT": [0.0, 0.0, 0.2, 1.0] },
    { "NAME": "twinkleDensity", "TYPE": "float", "MIN": 1.0, "MAX": 20.0, "DEFAULT": 8.0 },
    { "NAME": "twinkling", "TYPE": "float", "MIN": 1.0, "MAX": 8.0, "DEFAULT": 3.0 }
  ]
}*/

float hash(vec2 p) {
  float h = dot(p, vec2(127.1, 311.7));
  return fract(sin(h) * 43758.5453123);
}

void main() {
  vec2 uv = isf_FragNormCoord;
  vec2 grid = uv * twinkleDensity;
  vec2 gridCell = floor(grid);

  float closestDist = 1.0;
  float twinkleVal = 0.0;

  for (int dx = -1; dx <= 1; dx++) {
    for (int dy = -1; dy <= 1; dy++) {
      vec2 neighbor = gridCell + vec2(float(dx), float(dy));
      float seedx = hash(neighbor);
      float seedy = hash(neighbor + vec2(73.2, 24.8));

      vec2 starPos = neighbor + vec2(seedx, seedy);
      float dist = length(grid - starPos);

      if (dist < closestDist) {
        closestDist = dist;
        float twinklePhase = hash(neighbor + vec2(41.1, 83.4)) * 6.283185307;
        twinkleVal = 0.5 + 0.5 * sin(TIME * twinkling + twinklePhase);
        twinkleVal = smoothstep(0.6, 0.0, dist) * twinkleVal;
      }
    }
  }

  vec3 finalColor = mix(backgroundColor.rgb, starColor.rgb, twinkleVal);
  gl_FragColor = vec4(finalColor, 1.0);
}

/*{
  "DESCRIPTION": "Chasing lights running left to right along the roofline",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.5 },
    { "NAME": "spacing", "TYPE": "float", "MIN": 0.05, "MAX": 0.5, "DEFAULT": 0.15 },
    { "NAME": "width", "TYPE": "float", "MIN": 0.01, "MAX": 0.3, "DEFAULT": 0.08 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  float chase = mod(uv.x + TIME * speed * 0.5, spacing);
  float pulse = smoothstep(width, 0.0, abs(chase - width * 0.5));

  float brightness = pulse * (0.6 + 0.4 * sin(TIME * 3.0 + uv.x * 6.28));

  vec3 color = mix(colorA.rgb, colorB.rgb, sin(uv.x * 3.14159 + TIME) * 0.5 + 0.5);

  gl_FragColor = vec4(color * brightness, 1.0);
}

/*{
  "DESCRIPTION": "Swirling plasma effect with animated color cycling",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 1.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [1.0, 0.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 4.0, "DEFAULT": 2.0 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord * scale;

  float angle = atan(uv.y - 0.5, uv.x - 0.5);
  float dist = length(uv - 0.5);

  float wave1 = sin(angle * 3.0 + TIME * speed - dist * 4.0) * 0.5 + 0.5;
  float wave2 = cos(angle * 2.0 - TIME * speed * 0.7 + dist * 3.0) * 0.5 + 0.5;
  float wave3 = sin(dist * 6.0 - TIME * speed * 1.3 + angle) * 0.5 + 0.5;

  float plasma = (wave1 + wave2 + wave3) / 3.0;

  vec3 color = mix(colorA.rgb, colorB.rgb, wave1);
  color = mix(color, colorC.rgb, wave2);

  gl_FragColor = vec4(color * (0.7 + plasma * 0.3), 1.0);
}

/*{
  "DESCRIPTION": "Rainbow colors sweep continuously across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "width", "TYPE": "float", "MIN": 0.1, "MAX": 2.0, "DEFAULT": 0.5 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  float sweep = fract(uv.x - TIME * speed * 0.5);
  float hue = fract(sweep + uv.y * width);

  float h = hue * 6.0;
  float c = 1.0;
  float x = c * (1.0 - abs(mod(h, 2.0) - 1.0));

  vec3 rgb;
  if (h < 1.0) rgb = vec3(c, x, 0.0);
  else if (h < 2.0) rgb = vec3(x, c, 0.0);
  else if (h < 3.0) rgb = vec3(0.0, c, x);
  else if (h < 4.0) rgb = vec3(0.0, x, c);
  else if (h < 5.0) rgb = vec3(x, 0.0, c);
  else rgb = vec3(c, 0.0, x);

  gl_FragColor = vec4(rgb, 1.0);
}

/*{
  "DESCRIPTION": "Lights pulsing to a steady beat with color cycling",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.0, 0.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "intensity", "TYPE": "float", "MIN": 0.2, "MAX": 1.0, "DEFAULT": 0.8 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  float beat = TIME * speed;
  float pulse = 0.5 + 0.5 * sin(beat * 6.283185);
  pulse = pow(pulse, 2.0);

  float colorCycle = mod(TIME * speed * 0.3, 3.0);
  vec3 color;
  if (colorCycle < 1.0) {
    color = mix(colorA.rgb, colorB.rgb, colorCycle);
  } else if (colorCycle < 2.0) {
    color = mix(colorB.rgb, colorC.rgb, colorCycle - 1.0);
  } else {
    color = mix(colorC.rgb, colorA.rgb, colorCycle - 2.0);
  }

  float brightness = mix(1.0 - intensity, 1.0, pulse);

  gl_FragColor = vec4(color * brightness, 1.0);
}

/*{
  "DESCRIPTION": "American flag waving in the breeze",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "waveAmplitude", "TYPE": "float", "MIN": 0.0, "MAX": 0.3, "DEFAULT": 0.08 },
    { "NAME": "waveFrequency", "TYPE": "float", "MIN": 0.5, "MAX": 4.0, "DEFAULT": 2.0 },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.5 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  // Create wave distortion based on y position
  float wavePhase = TIME * speed;
  float wavey = uv.y + sin(uv.y * waveFrequency * 6.28318 + wavePhase) * waveAmplitude;

  // Clamp wave to valid range
  wavey = clamp(wavey, 0.0, 1.0);

  // Adjust x based on wave for a flag-like effect
  float distortedX = uv.x + sin(wavey * 3.14159) * waveAmplitude * 0.5;

  // Three vertical stripes: red, white, blue
  vec3 color = vec3(0.0);

  if (distortedX < 0.33333) {
    // Red stripe (left third)
    color = vec3(1.0, 0.0, 0.0);
  } else if (distortedX < 0.66667) {
    // White stripe (middle third)
    color = vec3(1.0, 1.0, 1.0);
  } else {
    // Blue stripe (right third)
    color = vec3(0.0, 0.1, 0.5);
  }

  // Add subtle star pattern in blue section for authenticity
  if (distortedX > 0.66667) {
    float starY = fract(wavey * 6.0) - 0.5;
    float starX = fract(distortedX * 8.0) - 0.5;
    float starDist = length(vec2(starX, starY));
    float star = smoothstep(0.15, 0.05, starDist);
    color = mix(color, vec3(1.0, 1.0, 1.0), star * 0.6);
  }

  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "Spooky green fog drifting across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "fogColor", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "density", "TYPE": "float", "MIN": 0.0, "MAX": 2.0, "DEFAULT": 1.0 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.1, "MAX": 5.0, "DEFAULT": 2.0 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  float drift = TIME * speed * 0.3;

  float fog = 0.0;

  for(int i = 0; i < 4; i++) {
    float layer = fract((uv.x - drift * (0.5 + float(i) * 0.25)) / scale);
    float wave = sin(uv.y * 3.14159 * 2.0 * scale + float(i) * 1.57 + TIME * speed * 0.5) * 0.5 + 0.5;
    float noise = sin(layer * 12.566 + float(i) * 2.0) * 0.5 + 0.5;
    fog += noise * wave * 0.25;
  }

  fog = smoothstep(0.2, 0.8, fog * density);

  gl_FragColor = vec4(fogColor.rgb * fog, 1.0);
}

/*{
  "DESCRIPTION": "A spinning tunnel you fly through with rotating stripes",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.5 },
    { "NAME": "scale", "TYPE": "float", "MIN": 1.0, "MAX": 20.0, "DEFAULT": 8.0 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord - vec2(0.5, 0.5);

  float dist = length(uv);
  float angle = atan(uv.y, uv.x);

  float depth = 1.0 / (dist + 0.1);
  float spin = angle + TIME * speed;

  float pattern = fract(spin / 6.283185307 * scale + depth * 2.0);
  float band = step(0.5, pattern);

  vec3 color = mix(colorA.rgb, colorB.rgb, band);
  float brightness = smoothstep(0.0, 1.0, depth * 0.8);

  gl_FragColor = vec4(color * brightness, 1.0);
}

/*{
  "DESCRIPTION": "Ocean waves rolling horizontally with color transitions",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.0, 0.2, 0.8, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 0.5, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "waveHeight", "TYPE": "float", "MIN": 0.1, "MAX": 2.0, "DEFAULT": 0.8 },
    { "NAME": "waveFreq", "TYPE": "float", "MIN": 0.5, "MAX": 4.0, "DEFAULT": 2.0 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  float wave1 = sin(uv.x * waveFreq * 3.14159 - TIME * speed * 2.0) * waveHeight * 0.3;
  float wave2 = sin(uv.x * waveFreq * 1.57079 + TIME * speed * 1.5) * waveHeight * 0.2;
  float wave3 = sin(uv.x * waveFreq * 2.36 + TIME * speed * 1.0) * waveHeight * 0.15;

  float waves = wave1 + wave2 + wave3;

  float yWarp = uv.y + waves * 0.5;
  yWarp = mod(yWarp, 1.0);

  float brightness = smoothstep(0.3, 0.5, yWarp) - smoothstep(0.5, 0.8, yWarp);
  brightness += sin(uv.x * waveFreq - TIME * speed) * 0.2;
  brightness = clamp(brightness, 0.0, 1.0);

  vec3 waveColor = mix(colorA.rgb, colorB.rgb, sin(TIME * speed * 0.5 + uv.x) * 0.5 + 0.5);

  vec3 finalColor = waveColor * (0.5 + brightness * 0.8);

  gl_FragColor = vec4(finalColor, 1.0);
}

/*{
  "DESCRIPTION": "Slow lava lamp blobs flowing smoothly across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 2.0, "DEFAULT": 0.5 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 4.0, "DEFAULT": 2.0 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  vec2 pos = uv * scale;

  float blob1 = sin(pos.x + TIME * speed * 0.3) * 0.5 + 0.5;
  blob1 = blob1 * sin(pos.y * 2.0 + TIME * speed * 0.2) * 0.5 + 0.5;

  float blob2 = sin(pos.x * 1.5 + TIME * speed * 0.25 + 3.0) * 0.5 + 0.5;
  blob2 = blob2 * sin(pos.y * 1.8 + TIME * speed * 0.15 + 2.0) * 0.5 + 0.5;

  float blob3 = sin(pos.x * 0.8 + TIME * speed * 0.35 + 6.0) * 0.5 + 0.5;
  blob3 = blob3 * sin(pos.y * 2.3 + TIME * speed * 0.25 + 4.0) * 0.5 + 0.5;

  float combined = max(max(blob1, blob2), blob3);
  combined = smoothstep(0.3, 0.7, combined);

  vec3 color = mix(colorA.rgb, colorB.rgb, blob1 * 0.5 + blob2 * 0.3 + blob3 * 0.2);

  gl_FragColor = vec4(color * combined, 1.0);
}

/*{
  "DESCRIPTION": "Alternating flashes between two colors",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 }
  ]
}*/

void main() {
  float phase = mod(TIME * speed, 2.0);
  vec3 color = mix(colorA.rgb, colorB.rgb, step(1.0, phase));
  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "Green streaks falling like digital rain across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 0.5, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 2.0 },
    { "NAME": "density", "TYPE": "float", "MIN": 0.1, "MAX": 8.0, "DEFAULT": 3.0 },
    { "NAME": "streakLength", "TYPE": "float", "MIN": 0.05, "MAX": 0.5, "DEFAULT": 0.2 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  float column = floor(uv.x * density);
  float seed = fract(sin(column * 12.9898) * 43758.5453);

  float fallPos = fract(uv.y + TIME * speed * 0.5 + seed);

  float streak = smoothstep(fallPos + streakLength, fallPos - 0.02, uv.y + TIME * speed * 0.5 + seed);
  streak *= smoothstep(-0.05, 0.1, fallPos);

  vec3 rainColor = mix(colorB.rgb, colorA.rgb, sin(fallPos * 3.14159) * 0.5 + 0.5);

  gl_FragColor = vec4(rainColor * streak, 1.0);
}

/*{
  "DESCRIPTION": "A slow breathing glow that expands and contracts across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "glowColor", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "breathSpeed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "glowIntensity", "TYPE": "float", "MIN": 0.1, "MAX": 2.0, "DEFAULT": 1.0 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;
  vec2 center = vec2(0.5, 0.5);
  float dist = length(uv - center);

  float breathe = sin(TIME * breathSpeed * 0.5) * 0.5 + 0.5;
  float radiusMax = 1.2;
  float radius = mix(0.3, radiusMax, breathe);

  float softEdge = smoothstep(radius + 0.3, radius - 0.1, dist);
  float glow = softEdge * glowIntensity;

  vec3 color = glowColor.rgb * glow;
  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "Fireworks bursting outward from random points with trailing sparks",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
